//! | `det_2` | max{x·y·z^3, x·y^3·z, x^3·y·z} | no | 18 + 150u + 554u^2 + 1190u^3 + 1638u^4 + 1498u^5 + 910u^6 + 354u^7 + 80u^8 + 8u^9 | 150u + 1002u^2 + 2414u^3 + 3246u^4 + 2730u^5 + 1474u^6 + 498u^7 + 96u^8 + 8u^9 |
//! | `det_3` | max{x·y·z^3, x·y^3·z, x^3·y·z} | no | 36 + 336u + 1408u^2 + 3488u^3 + 5656u^4 + 6272u^5 + 4816u^6 + 2528u^7 + 868u^8 + 176u^9 + 16u^10 | 336u + 2304u^2 + 5936u^3 + 8872u^4 + 8736u^5 + 5944u^6 + 2816u^7 + 900u^8 + 176u^9 + 16u^10 |
//! | `det_4` | max{x·y·z^3, x·y^3·z, x^3·y·z} | no | 18 + 150u + 554u^2 + 1190u^3 + 1638u^4 + 1498u^5 + 910u^6 + 354u^7 + 80u^8 + 8u^9 | 150u + 1002u^2 + 2414u^3 + 3246u^4 + 2730u^5 + 1474u^6 + 498u^7 + 96u^8 + 8u^9 |
//! | `det_5` | max{x·y·z^3, x·y^3·z, x^3·y·z} | no | 54 + 540u + 2448u^2 + 6640u^3 + 11972u^4 + 15064u^5 + 13496u^6 + 8608u^7 + 3830u^8 + 1132u^9 + 200u^10 + 16u^11 | 540u + 3792u^2 + 10312u^3 + 16796u^4 + 18760u^5 + 15188u^6 + 9040u^7 + 3878u^8 + 1132u^9 + 200u^10 + 16u^11 |
//! | `det_6` | max{x·y·z^3, x·y^3·z, x^3·y·z} | no | 18 + 150u + 554u^2 + 1190u^3 + 1638u^4 + 1498u^5 + 910u^6 + 354u^7 + 80u^8 + 8u^9 | 150u + 1002u^2 + 2414u^3 + 3246u^4 + 2730u^5 + 1474u^6 + 498u^7 + 96u^8 + 8u^9 |
//! | `det` | max{x·y·z^3, x·y^3·z, x^3·y·z} | no | 72 + 762u + 3692u^2 + 10832u^3 + 21440u^4 + 30172u^5 + 30968u^6 + 23368u^7 + 12872u^8 + 5050u^9 + 1340u^10 + 216u^11 + 16u^12 | 762u + 5484u^2 + 15728u^3 + 27872u^4 + 35100u^5 + 33224u^6 + 23944u^7 + 12936u^8 + 5050u^9 + 1340u^10 + 216u^11 + 16u^12 |
//!
//! The filter computes the scale S at run time at least (1 − u)^4 times its exact value: 4
//! rounding(s), each product counting its own and both its operands', each `larger` the larger of
//! its operands'. It computes the bound as the constant times S, one more rounding: k = 4 + 1. The
//! constant is E · (1 + 2u)^k, rounded up to an `f64`.
//!
//! | Quantity | Value |
//! | --- | --- |
//! | Result | `det` |
//! | Unit error E | 762u + 5484u^2 + 15728u^3 + 27872u^4 + 35100u^5 + 33224u^6 + 23944u^7 + 12936u^8 + 5050u^9 + 1340u^10 + 216u^11 + 16u^12 |
//! | Scale S | max{x·y·z^3, x·y^3·z, x^3·y·z} |
//! | Scale at run time | `m_x * m_y * m_z * larger(larger(m_z * m_z, m_y * m_y), m_x * m_x)` |
//! | Roundings k | 5 |
//! | Constant, exactly | 762u + 13104u^2 + 101048u^3 + 465472u^4 + 1442620u^5 + 3220448u^6 + 5423672u^7 + 7122392u^8 + 7449994u^9 + 6265920u^10 + 4229184u^11 + 2260864u^12 + 933952u^13 + 286720u^14 + 61440u^15 + 8192u^16 + 512u^17 |
//! | Constant as an `f64` | `0x3d37d0000000000d` = 6702622882922509 · 2^-96 ≈ 8.459899447643709e-14 |
//!
//! Cost: the filter is 86 `f64` operations, then 12 magnitudes and their maxima and the bound's 7
//! multiplication(s); the exact path, run only when the filter cannot decide, is 86 checked integer
//! operations.

use crate::grid::P3;
use crate::sign::Sign;
use crate::wide::I256;

use super::{decide, exact_f64, larger, largest_magnitude};

/// The filter's error constant: E · (1 + 2u)^5 with E = 762u + 5484u^2 + 15728u^3 + 27872u^4 +
/// 35100u^5 + 33224u^6 + 23944u^7 + 12936u^8 + 5050u^9 + 1340u^10 + 216u^11 + 16u^12, the result's
/// unit error (header), rounded up to an `f64`: 6702622882922509 · 2^-96.
const ERROR: f64 = f64::from_bits(0x3d37_d000_0000_000d);

/// `insphere`'s sign from its `f64` filter, or `None` when the filter's bound cannot certify it.
///
/// `Some(Sign::Zero)` only when the scale is zero, which makes the exact value zero.
#[inline]
#[must_use]
#[allow(
    clippy::many_single_char_names,
    clippy::similar_names,
    reason = "names, parameters and lines follow the description: one per input and step"
)]
pub fn filter(a: P3, b: P3, c: P3, d: P3, e: P3) -> Option<Sign> {
    let ae_x = exact_f64(a.x) - exact_f64(e.x);
    let ae_y = exact_f64(a.y) - exact_f64(e.y);
    let ae_z = exact_f64(a.z) - exact_f64(e.z);
    let be_x = exact_f64(b.x) - exact_f64(e.x);
    let be_y = exact_f64(b.y) - exact_f64(e.y);
    let be_z = exact_f64(b.z) - exact_f64(e.z);
    let ce_x = exact_f64(c.x) - exact_f64(e.x);
    let ce_y = exact_f64(c.y) - exact_f64(e.y);
    let ce_z = exact_f64(c.z) - exact_f64(e.z);
    let de_x = exact_f64(d.x) - exact_f64(e.x);
    let de_y = exact_f64(d.y) - exact_f64(e.y);
    let de_z = exact_f64(d.z) - exact_f64(e.z);
    let a_lift_1 = ae_x * ae_x;
    let a_lift_2 = ae_y * ae_y;
    let a_lift_3 = a_lift_1 + a_lift_2;
    let a_lift_4 = ae_z * ae_z;
    let a_lift = a_lift_3 + a_lift_4;
    let b_lift_1 = be_x * be_x;
    let b_lift_2 = be_y * be_y;
    let b_lift_3 = b_lift_1 + b_lift_2;
    let b_lift_4 = be_z * be_z;
    let b_lift = b_lift_3 + b_lift_4;
    let c_lift_1 = ce_x * ce_x;
    let c_lift_2 = ce_y * ce_y;
    let c_lift_3 = c_lift_1 + c_lift_2;
    let c_lift_4 = ce_z * ce_z;
    let c_lift = c_lift_3 + c_lift_4;
    let d_lift_1 = de_x * de_x;
    let d_lift_2 = de_y * de_y;
    let d_lift_3 = d_lift_1 + d_lift_2;
    let d_lift_4 = de_z * de_z;
    let d_lift = d_lift_3 + d_lift_4;
    let cd_x_1 = ce_y * de_z;
    let cd_x_2 = ce_z * de_y;
    let cd_x = cd_x_1 - cd_x_2;
    let cd_y_1 = ce_z * de_x;
    let cd_y_2 = ce_x * de_z;
    let cd_y = cd_y_1 - cd_y_2;
    let cd_z_1 = ce_x * de_y;
    let cd_z_2 = ce_y * de_x;
    let cd_z = cd_z_1 - cd_z_2;
    let bd_x_1 = be_y * de_z;
    let bd_x_2 = be_z * de_y;
    let bd_x = bd_x_1 - bd_x_2;
    let bd_y_1 = be_z * de_x;
    let bd_y_2 = be_x * de_z;
    let bd_y = bd_y_1 - bd_y_2;
    let bd_z_1 = be_x * de_y;
    let bd_z_2 = be_y * de_x;
    let bd_z = bd_z_1 - bd_z_2;
    let bc_x_1 = be_y * ce_z;
    let bc_x_2 = be_z * ce_y;
    let bc_x = bc_x_1 - bc_x_2;
    let bc_y_1 = be_z * ce_x;
    let bc_y_2 = be_x * ce_z;
    let bc_y = bc_y_1 - bc_y_2;
    let bc_z_1 = be_x * ce_y;
    let bc_z_2 = be_y * ce_x;
    let bc_z = bc_z_1 - bc_z_2;
    let bcd_1 = be_x * cd_x;
    let bcd_2 = be_y * cd_y;
    let bcd_3 = bcd_1 + bcd_2;
    let bcd_4 = be_z * cd_z;
    let bcd = bcd_3 + bcd_4;
    let acd_1 = ae_x * cd_x;
    let acd_2 = ae_y * cd_y;
    let acd_3 = acd_1 + acd_2;
    let acd_4 = ae_z * cd_z;
    let acd = acd_3 + acd_4;
    let abd_1 = ae_x * bd_x;
    let abd_2 = ae_y * bd_y;
    let abd_3 = abd_1 + abd_2;
    let abd_4 = ae_z * bd_z;
    let abd = abd_3 + abd_4;
    let abc_1 = ae_x * bc_x;
    let abc_2 = ae_y * bc_y;
    let abc_3 = abc_1 + abc_2;
    let abc_4 = ae_z * bc_z;
    let abc = abc_3 + abc_4;
    let det_1 = a_lift * bcd;
    let det_2 = b_lift * acd;
    let det_3 = det_1 - det_2;
    let det_4 = c_lift * abd;
    let det_5 = det_3 + det_4;
    let det_6 = d_lift * abc;
    let det = det_5 - det_6;
    let m_x = largest_magnitude([ae_x, be_x, ce_x, de_x]);
    let m_y = largest_magnitude([ae_y, be_y, ce_y, de_y]);
    let m_z = largest_magnitude([ae_z, be_z, ce_z, de_z]);
    let scale = m_x * m_y * m_z * larger(larger(m_z * m_z, m_y * m_y), m_x * m_x);
    decide(det, ERROR, scale)
}

/// `insphere`'s exact value: each step in the type its certificate gives it, with checked
/// arithmetic; `None` only if a step overflowed, which the certificate rules out.
#[inline]
#[must_use]
#[allow(
    clippy::many_single_char_names,
    clippy::similar_names,
    reason = "names, parameters and lines follow the description: one per input and step"
)]
pub fn value(a: P3, b: P3, c: P3, d: P3, e: P3) -> Option<I256> {
    let ae_x = a.x.get().checked_sub(e.x.get())?;
    let ae_y = a.y.get().checked_sub(e.y.get())?;
    let ae_z = a.z.get().checked_sub(e.z.get())?;
    let be_x = b.x.get().checked_sub(e.x.get())?;
    let be_y = b.y.get().checked_sub(e.y.get())?;
    let be_z = b.z.get().checked_sub(e.z.get())?;
    let ce_x = c.x.get().checked_sub(e.x.get())?;
    let ce_y = c.y.get().checked_sub(e.y.get())?;
    let ce_z = c.z.get().checked_sub(e.z.get())?;
    let de_x = d.x.get().checked_sub(e.x.get())?;
    let de_y = d.y.get().checked_sub(e.y.get())?;
    let de_z = d.z.get().checked_sub(e.z.get())?;
    let a_lift_1 = i128::from(ae_x).checked_mul(i128::from(ae_x))?;
    let a_lift_2 = i128::from(ae_y).checked_mul(i128::from(ae_y))?;
    let a_lift_3 = a_lift_1.checked_add(a_lift_2)?;
    let a_lift_4 = i128::from(ae_z).checked_mul(i128::from(ae_z))?;
    let a_lift = a_lift_3.checked_add(a_lift_4)?;
    let b_lift_1 = i128::from(be_x).checked_mul(i128::from(be_x))?;
    let b_lift_2 = i128::from(be_y).checked_mul(i128::from(be_y))?;
    let b_lift_3 = b_lift_1.checked_add(b_lift_2)?;
    let b_lift_4 = i128::from(be_z).checked_mul(i128::from(be_z))?;
    let b_lift = b_lift_3.checked_add(b_lift_4)?;
    let c_lift_1 = i128::from(ce_x).checked_mul(i128::from(ce_x))?;
    let c_lift_2 = i128::from(ce_y).checked_mul(i128::from(ce_y))?;
    let c_lift_3 = c_lift_1.checked_add(c_lift_2)?;
    let c_lift_4 = i128::from(ce_z).checked_mul(i128::from(ce_z))?;
    let c_lift = c_lift_3.checked_add(c_lift_4)?;
    let d_lift_1 = i128::from(de_x).checked_mul(i128::from(de_x))?;
    let d_lift_2 = i128::from(de_y).checked_mul(i128::from(de_y))?;
    let d_lift_3 = d_lift_1.checked_add(d_lift_2)?;
    let d_lift_4 = i128::from(de_z).checked_mul(i128::from(de_z))?;
    let d_lift = d_lift_3.checked_add(d_lift_4)?;
    let cd_x_1 = i128::from(ce_y).checked_mul(i128::from(de_z))?;
    let cd_x_2 = i128::from(ce_z).checked_mul(i128::from(de_y))?;
    let cd_x = cd_x_1.checked_sub(cd_x_2)?;
    let cd_y_1 = i128::from(ce_z).checked_mul(i128::from(de_x))?;
    let cd_y_2 = i128::from(ce_x).checked_mul(i128::from(de_z))?;
    let cd_y = cd_y_1.checked_sub(cd_y_2)?;
    let cd_z_1 = i128::from(ce_x).checked_mul(i128::from(de_y))?;
    let cd_z_2 = i128::from(ce_y).checked_mul(i128::from(de_x))?;
    let cd_z = cd_z_1.checked_sub(cd_z_2)?;
    let bd_x_1 = i128::from(be_y).checked_mul(i128::from(de_z))?;
    let bd_x_2 = i128::from(be_z).checked_mul(i128::from(de_y))?;
    let bd_x = bd_x_1.checked_sub(bd_x_2)?;
    let bd_y_1 = i128::from(be_z).checked_mul(i128::from(de_x))?;
    let bd_y_2 = i128::from(be_x).checked_mul(i128::from(de_z))?;
    let bd_y = bd_y_1.checked_sub(bd_y_2)?;
    let bd_z_1 = i128::from(be_x).checked_mul(i128::from(de_y))?;
    let bd_z_2 = i128::from(be_y).checked_mul(i128::from(de_x))?;
    let bd_z = bd_z_1.checked_sub(bd_z_2)?;
    let bc_x_1 = i128::from(be_y).checked_mul(i128::from(ce_z))?;
    let bc_x_2 = i128::from(be_z).checked_mul(i128::from(ce_y))?;
    let bc_x = bc_x_1.checked_sub(bc_x_2)?;
    let bc_y_1 = i128::from(be_z).checked_mul(i128::from(ce_x))?;
    let bc_y_2 = i128::from(be_x).checked_mul(i128::from(ce_z))?;
    let bc_y = bc_y_1.checked_sub(bc_y_2)?;
    let bc_z_1 = i128::from(be_x).checked_mul(i128::from(ce_y))?;
    let bc_z_2 = i128::from(be_y).checked_mul(i128::from(ce_x))?;
    let bc_z = bc_z_1.checked_sub(bc_z_2)?;
    let bcd_1 = i128::from(be_x).checked_mul(cd_x)?;
    let bcd_2 = i128::from(be_y).checked_mul(cd_y)?;
    let bcd_3 = bcd_1.checked_add(bcd_2)?;
    let bcd_4 = i128::from(be_z).checked_mul(cd_z)?;
    let bcd = bcd_3.checked_add(bcd_4)?;
    let acd_1 = i128::from(ae_x).checked_mul(cd_x)?;
    let acd_2 = i128::from(ae_y).checked_mul(cd_y)?;
    let acd_3 = acd_1.checked_add(acd_2)?;
    let acd_4 = i128::from(ae_z).checked_mul(cd_z)?;
    let acd = acd_3.checked_add(acd_4)?;
    let abd_1 = i128::from(ae_x).checked_mul(bd_x)?;
    let abd_2 = i128::from(ae_y).checked_mul(bd_y)?;
    let abd_3 = abd_1.checked_add(abd_2)?;
    let abd_4 = i128::from(ae_z).checked_mul(bd_z)?;
    let abd = abd_3.checked_add(abd_4)?;
    let abc_1 = i128::from(ae_x).checked_mul(bc_x)?;
    let abc_2 = i128::from(ae_y).checked_mul(bc_y)?;
    let abc_3 = abc_1.checked_add(abc_2)?;
    let abc_4 = i128::from(ae_z).checked_mul(bc_z)?;
    let abc = abc_3.checked_add(abc_4)?;
    let det_1 = I256::from_i128(a_lift).checked_mul(&I256::from_i128(bcd))?;
    let det_2 = I256::from_i128(b_lift).checked_mul(&I256::from_i128(acd))?;
    let det_3 = det_1.checked_sub(&det_2)?;
    let det_4 = I256::from_i128(c_lift).checked_mul(&I256::from_i128(abd))?;
    let det_5 = det_3.checked_add(&det_4)?;
    let det_6 = I256::from_i128(d_lift).checked_mul(&I256::from_i128(abc))?;
    let det = det_5.checked_sub(&det_6)?;
    Some(det)
}

/// `insphere`'s exact sign: the sign of [`value`], or `None` as for [`value`].
#[inline]
#[must_use]
#[allow(
    clippy::many_single_char_names,
    reason = "one-letter names are the description's points"
)]
pub fn exact(a: P3, b: P3, c: P3, d: P3, e: P3) -> Option<Sign> {
    value(a, b, c, d, e).map(|v| v.signum())
}
